excels.excel:

EXPORT WITH SHEET="增值税税负分析表", HEADER=true,
    MAPPING={"a":"期间","b":"销售收入","c":"销项税额","d":"进项税额","e":"应纳增值税","f":"税负率"},
    FORMAT={"b":"#,##0.00","c":"#,##0.00","d":"#,##0.00","e":"#,##0.00","f":"0.00%"},
    FORMULAS={
        E2:'C2-D2',F2:'E2/B2',
        E3:'C3-D3',F3:'E3/B3',
        E4:'C4-D4',F4:'E4/B4',
        E5:'C5-D5',F5:'E5/B5',
        B6:'SUM(B2:B5)',C6:'SUM(C2:C5)',D6:'SUM(D2:D5)',E6:'C6-D6',F6:'E6/B6'
    },
    STYLE={
        ROW 6:{bold:true,fillPattern:solid_foreground,fillForegroundColor:lightYellow,alignment:right,verticalAlignment:center},
        F4:{color:red,bold:true}
    }
